// Gera uma URL de busca do Google News para cada termo configurado,
// cobrindo os dias desde a última execução
const { termos_de_busca } = $('Configuração').first().json;
const { dias_busca } = $('Calcular janela').first().json;

return termos_de_busca.map((termo) => ({
  json: {
    termo,
    url: 'https://news.google.com/rss/search?q=' + encodeURIComponent(`${termo} when:${dias_busca}d`) +
      '&hl=pt-BR&gl=BR&ceid=BR:pt-419',
  },
}));

// Limpeza: junta as notícias de todos os termos, remove as repetidas,
// mantém só as publicadas dentro da janela e tira as que já foram enviadas.
const { horas_janela } = $('Calcular janela').first().json;
const agora = Date.now();

// Deixa o texto comparável: minúsculo, sem acento e sem pontuação
const normalizar = (texto) =>
  texto.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();

// O link do Google News às vezes muda, por isso a notícia enviada é reconhecida
// pelo link ou pela combinação de título e veículo
const enviadas = new Set();
for (const { json: n } of $('Ler notícias').all()) {
  if (!n.link) continue; // planilha vazia
  enviadas.add(n.link);
  enviadas.add(normalizar(String(n.titulo)) + '|' + normalizar(String(n.veiculo)));
}

const vistos = new Set();
const noticias = [];
let coletadas = 0, duplicadas = 0, antigas = 0, ja_enviadas = 0, erros = 0;

for (const item of $input.all()) {
  const n = item.json;

  // Se um RSS falhou, o n8n entrega um item com "error" no lugar da notícia
  if (n.error || !n.title || !n.link) { erros++; continue; }
  coletadas++;

  // O Google News escreve o título como "Título da matéria - Veículo"
  const corte = n.title.lastIndexOf(' - ');
  const titulo = (corte > 0 ? n.title.slice(0, corte) : n.title).trim().replace(/[\s-]+$/, '');
  const veiculo = corte > 0 ? n.title.slice(corte + 3).trim() : 'Desconhecido';

  // Mesma matéria no mesmo veículo = repetida. Em veículos diferentes, conta as duas
  const chave = normalizar(titulo) + '|' + normalizar(veiculo);
  if (vistos.has(chave) || vistos.has(n.link)) { duplicadas++; continue; }
  vistos.add(chave);
  vistos.add(n.link);

  if (enviadas.has(chave) || enviadas.has(n.link)) { ja_enviadas++; continue; }

  const data = new Date(n.isoDate || n.pubDate);
  if (isNaN(data) || agora - data.getTime() > horas_janela * 60 * 60 * 1000) { antigas++; continue; }

  noticias.push({
    titulo,
    veiculo,
    data: data.toISOString(),
    link: n.link,
    trecho: (n.contentSnippet || '').replace(/\s+/g, ' ').trim(),
  });
}

// Mais recentes primeiro
noticias.sort((a, b) => b.data.localeCompare(a.data));

// Os números da coleta vão junto em cada notícia, para o log da Fase 5
const resumo_coleta = { inicio: new Date(agora).toISOString(), horas_janela, coletadas, duplicadas, fora_da_janela: antigas, ja_enviadas, erros_rss: erros, aproveitadas: noticias.length };

return noticias.map((noticia) => ({ json: { ...noticia, resumo_coleta } }));

// Agrupa as notícias em lotes de 10 para a triagem.
// Cada notícia ganha um id (1 a 10 dentro do lote) para conferir a resposta da IA.
const TAMANHO_LOTE = 10;
const config = $('Configuração').first().json;
const noticias = $input.all().map(({ json: { resumo_coleta, ...noticia } }) => noticia);

const mensagens = config.mensagens_chave.map((m) => '- ' + m).join('\n');

const lotes = [];
for (let i = 0; i < noticias.length; i += TAMANHO_LOTE) {
  const grupo = noticias.slice(i, i + TAMANHO_LOTE).map((n, j) => ({ id: j + 1, ...n }));
  const lista = grupo.map((n) => `[${n.id}] (${n.veiculo}) ${n.titulo}`).join('\n');
  lotes.push({
    json: {
      lote: lotes.length + 1,
      tema: config.tema,
      foco_do_cliente: config.foco_do_cliente,
      noticias: grupo,
      mensagem: `Mensagens-chave configuradas:\n${mensagens}\n\nNotícias:\n${lista}`,
    },
  });
}

return lotes;

// Junta a resposta da IA com os dados de cada notícia e confere se voltaram todos os ids.
// Notícia sem classificação (lote com erro ou id faltando) é descartada e registrada.
const SENTIMENTOS = ['positivo', 'neutro', 'negativo'];
const ADERENCIAS = ['alta', 'media', 'baixa'];
const mensagensConfiguradas = $('Configuração').first().json.mensagens_chave;

const noticias = [];
const erros = [];
let descartadas = 0;

$input.all().forEach((item, i) => {
  const lote = $('Montar lotes').itemMatching(i).json;
  const classificacoes = item.json.output?.classificacoes;

  if (!Array.isArray(classificacoes)) {
    descartadas += lote.noticias.length;
    erros.push(`Lote ${lote.lote}: ${item.json.error || 'resposta sem classificações'}`);
    return;
  }

    // A IA às vezes devolve o id como texto ("1" ou "[1]"); aqui vira número
  const porId = new Map(classificacoes.map((c) => [Number(String(c.id).replace(/\D/g, '')), c]));
  for (const { id, ...noticia } of lote.noticias) {
    const c = porId.get(id);
    if (!c) {
      descartadas++;
      erros.push(`Lote ${lote.lote}: notícia ${id} voltou sem classificação`);
      continue;
    }
    noticias.push({
      ...noticia,
      relevante: c.relevante === true,
      sentimento: SENTIMENTOS.includes(c.sentimento) ? c.sentimento : 'neutro',
      aderencia: ADERENCIAS.includes(c.aderencia) ? c.aderencia : 'baixa',
      // Só aceita mensagens-chave que existem na Configuração (a IA não pode inventar)
      mensagens_chave: (c.mensagens_chave || []).filter((m) => mensagensConfiguradas.includes(m)),
      resumo: c.resumo,
      motivo: c.motivo,
    });
  }
});

const resumo_triagem = {
  classificadas: noticias.length,
  relevantes: noticias.filter((n) => n.relevante).length,
  descartadas_por_erro: descartadas,
  erros,
};

return noticias.map((noticia) => ({ json: { ...noticia, resumo_triagem } }));

// Junta todas as notícias classificadas numa lista única para o Redator.
// Vão também as não relevantes: se uma cópia da mesma notícia foi relevante,
// o grupo inteiro entra no relatório (regra aplicada no Validar redação).
const config = $('Configuração').first().json;
const itens = $input.all().map((item) => item.json);
const { resumo_triagem } = itens[0];
const noticias = itens.map(({ resumo_triagem, ...n }, i) => ({ id: i + 1, ...n }));

const lista = noticias
  .map((n) => `${n.id}. [${n.relevante ? 'relevante' : 'não relevante'}, aderência ${n.aderencia}] (${n.veiculo}) ${n.titulo}`)
  .join('\n');

return [{ json: {
  tema: config.tema,
  foco_do_cliente: config.foco_do_cliente,
  noticias,
  resumo_triagem,
  mensagem: `Notícias do período (${noticias.length}):\n${lista}`,
} }];

// Confere a resposta do Redator e aplica as regras de grupo:
// - todo id precisa estar em um grupo (os que faltarem viram grupos sozinhos);
// - o grupo entra no relatório se pelo menos uma cópia foi relevante;
// - tom e aderência do grupo: o que a maioria das cópias relevantes recebeu.
const entrada = $('Preparar redação').first().json;
const resposta = $input.first().json;
const porId = new Map(entrada.noticias.map((n) => [n.id, n]));
const erros = [];

// Valor mais frequente; no empate, vence o que aparece primeiro em "prioridade"
const maioria = (valores, prioridade) => {
  const contagem = {};
  valores.forEach((v) => (contagem[v] = (contagem[v] || 0) + 1));
  return prioridade.reduce((melhor, v) => ((contagem[v] || 0) > (contagem[melhor] || 0) ? v : melhor));
};

const gruposIa = Array.isArray(resposta.output?.grupos) ? resposta.output.grupos : [];
if (!gruposIa.length) erros.push(`Redator: ${resposta.error || 'resposta sem grupos'}`);

const usados = new Set();
const grupos = [];
for (const g of gruposIa) {
  const membros = [];
  for (const bruto of g.ids || []) {
    // A IA às vezes devolve o id como texto ("1" ou "[1]"); aqui vira número
    const id = Number(String(bruto).replace(/\D/g, ''));
    if (!porId.has(id) || usados.has(id)) continue; // id inventado ou repetido
    usados.add(id);
    membros.push(porId.get(id));
  }
  if (membros.length) grupos.push({ membros, resumo: (g.resumo || '').trim() });
}

// Notícias que o Redator esqueceu viram grupos sozinhas
for (const n of entrada.noticias) {
  if (usados.has(n.id)) continue;
  grupos.push({ membros: [n], resumo: '' });
  if (gruposIa.length) erros.push(`Redator: notícia ${n.id} ficou fora dos grupos`);
}

const relevantes = grupos
  .filter(({ membros }) => membros.some((n) => n.relevante))
  .map(({ membros, resumo }) => {
    const copiasRelevantes = membros.filter((n) => n.relevante);
    return {
      titulo: copiasRelevantes[0].titulo,
      // Sem resumo do Redator, usa o resumo que a Triagem fez
      resumo: resumo || copiasRelevantes[0].resumo,
      sentimento: maioria(copiasRelevantes.map((n) => n.sentimento), ['negativo', 'neutro', 'positivo']),
      aderencia: maioria(copiasRelevantes.map((n) => n.aderencia), ['alta', 'media', 'baixa']),
      mensagens_chave: [...new Set(membros.flatMap((n) => n.mensagens_chave))],
      insercoes: membros.map(({ titulo, veiculo, link, data }) => ({ titulo, veiculo, link, data })),
    };
  });

const resumo_redacao = {
  grupos_relevantes: relevantes.length,
  insercoes: relevantes.reduce((total, g) => total + g.insercoes.length, 0),
  erros,
};

return [{ json: {
  panorama: (resposta.output?.panorama || '').trim(),
  grupos: relevantes,
  resumo_triagem: entrada.resumo_triagem,
  resumo_redacao,
} }];

// Monta a mensagem do Revisor: cada texto escrito pela IA ao lado dos títulos que ela podia usar.
const { panorama, grupos } = $input.first().json;

const blocos = grupos.map((g, i) => [
  `Grupo ${i + 1}`,
  'Títulos:',
  ...[...new Set(g.insercoes.map((ins) => ins.titulo))].map((t) => `- ${t}`),
  `Resumo: ${g.resumo}`,
].join('\n'));

return [{ json: {
  mensagem: [
    'PANORAMA (pode usar os títulos de todos os grupos):',
    panorama || '(sem panorama)',
    '',
    'GRUPOS:',
    blocos.join('\n\n'),
  ].join('\n'),
} }];

// Aplica a revisão: o que o Revisor apontou sai do relatório.
// Resumo com problema (ou que ficou sem conferência) é apagado e o grupo fica
// só com título e veículos; no panorama, saem só as frases com problema.
const entrada = $('Validar redação').first().json;
const resposta = $input.first().json;
const verificacoes = resposta.output?.verificacoes;
const grupos = entrada.grupos.map((g) => ({ ...g }));
let panorama = entrada.panorama;
const problemas = [];
const erros = [];

// Deixa o texto comparável: minúsculo, sem acento e sem pontuação
const normalizar = (texto) =>
  String(texto || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();

// Tira do panorama a frase apontada; se não encontrar, tira o panorama inteiro
const retirarDoPanorama = (frase) => {
  const alvo = normalizar(frase);
  const frases = panorama.split(/(?<=[.!?])\s+/).filter(Boolean);
  const restantes = frases.filter((f) => {
    const atual = normalizar(f);
    return !(alvo && (atual.includes(alvo) || alvo.includes(atual)));
  });
  panorama = !alvo || restantes.length === frases.length ? '' : restantes.join(' ');
};

if (!Array.isArray(verificacoes)) {
  // Sem revisão, nada do Redator vai para o relatório sem conferência
  erros.push(`Revisor: ${resposta.error || 'resposta sem verificações'}`);
  panorama = '';
  grupos.forEach((g) => (g.resumo = ''));
} else {
  let panoramaConferido = false;
  const conferidos = new Set();

  for (const v of verificacoes) {
    const fora = v.informacoes_fora_dos_titulos || [];
    if (/panorama/i.test(v.onde)) {
      panoramaConferido = true;
      if (!fora.length) continue;
      problemas.push(`Panorama: ${fora.join('; ')}`);
      const frases = v.frases_com_problema || [];
      if (!frases.length) panorama = '';
      frases.forEach((frase) => retirarDoPanorama(frase));
      continue;
    }
    const numero = Number(String(v.onde).replace(/\D/g, ''));
    const grupo = grupos[numero - 1];
    if (!grupo) {
      erros.push(`Revisor: verificou um grupo que não existe ("${v.onde}")`);
      continue;
    }
    conferidos.add(numero - 1);
    if (fora.length) {
      problemas.push(`Grupo ${numero}: ${fora.join('; ')}`);
      grupo.resumo = '';
    }
  }

  // O que o Revisor pulou não vai para o relatório sem conferência
  if (!panoramaConferido && panorama) {
    panorama = '';
    erros.push('Revisor: não conferiu o panorama');
  }
  grupos.forEach((g, i) => {
    if (!conferidos.has(i) && g.resumo) {
      g.resumo = '';
      erros.push(`Revisor: não conferiu o grupo ${i + 1}`);
    }
  });
}

const resumo_revisao = {
  problemas,
  resumos_retirados: grupos.filter((g, i) => entrada.grupos[i].resumo && !g.resumo).length,
  panorama_alterado: panorama !== entrada.panorama,
  erros,
};

return [{ json: { ...entrada, panorama, grupos, resumo_revisao } }];

// Monta o relatório final a partir dos dados já revisados.
// Só entram textos da IA que passaram pelo Revisor (panorama e resumos);
// títulos, veículos, links, contagens e a ordem vêm todos dos dados.
const entrada = $input.first().json;
const config = $('Configuração').first().json;
const coletadas = $('Limpeza').all().length;
const agora = $now.setZone('America/Sao_Paulo');
const edicao = agora.hour < 14 ? 'manhã' : 'noite';

// Formatação em HTML simples, aceito pelo Telegram e pelo Gmail
const escapar = (texto) => String(texto || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const veiculos = (g) => g.insercoes.map((i) => `<a href="${escapar(i.link)}">${escapar(i.veiculo)}</a>`).join(' · ');

// Em cada seção, as negativas vêm primeiro; depois, os fatos com mais veículos
const ordemTom = { negativo: 0, neutro: 1, positivo: 2 };
const ordenar = (lista) =>
  [...lista].sort((a, b) => ordemTom[a.sentimento] - ordemTom[b.sentimento] || b.insercoes.length - a.insercoes.length);
// Escreve "1 fato" ou "2 fatos"
const contar = (n, palavra) => `${n} ${palavra}${n === 1 ? '' : 's'}`;
const marca = (g) => (g.sentimento === 'negativo' ? '⚠️ ' : '');

const blocoCompleto = (g) => [`${marca(g)}<b>${escapar(g.titulo)}</b>`, g.resumo ? escapar(g.resumo) : null, veiculos(g)].filter(Boolean).join('\n');
const blocoCurto = (g) => `${marca(g)}${escapar(g.titulo)}\n${veiculos(g)}`;

const secao = (cabecalho, grupos, bloco) =>
  grupos.length ? [cabecalho, ...ordenar(grupos).map(bloco)].join('\n\n') : null;

const { grupos } = entrada;
const tom = (s) => grupos.filter((g) => g.sentimento === s).length;
const insercoes = grupos.reduce((total, g) => total + g.insercoes.length, 0);
const mensagens = config.mensagens_chave
  .map((m) => ({ m, total: grupos.filter((g) => g.mensagens_chave.includes(m)).length }))
  .filter(({ total }) => total > 0)
  .sort((a, b) => b.total - a.total);

const relatorio = [
  `📰 <b>Radar de Notícias – ${escapar(config.tema)}</b>\n${agora.toFormat('dd/LL/yyyy')} · edição da ${edicao}`,
  entrada.panorama ? `<b>PANORAMA</b>\n${escapar(entrada.panorama)}` : null,
  [
    '<b>NÚMEROS</b>',
    `• ${coletadas} ${coletadas === 1 ? 'notícia nova' : 'notícias novas'}`,
    `• ${contar(insercoes, 'relevante')}, sobre ${contar(grupos.length, 'fato')}`,
    `• Tom: ${contar(tom('negativo'), 'negativo')}, ${contar(tom('neutro'), 'neutro')}, ${contar(tom('positivo'), 'positivo')}`,
  ].join('\n'),
  secao('⭐ <b>DESTAQUES</b>', grupos.filter((g) => g.aderencia === 'alta'), blocoCompleto),
  secao('📌 <b>SETOR</b>', grupos.filter((g) => g.aderencia === 'media'), blocoCompleto),
  secao('🔎 <b>OUTRAS</b>', grupos.filter((g) => g.aderencia === 'baixa'), blocoCurto),
  mensagens.length
    ? ['<b>MENSAGENS-CHAVE</b>', ...mensagens.map(({ m, total }) => `• ${escapar(m)}: ${contar(total, 'fato')}`)].join('\n')
    : null,
]
  .filter(Boolean)
  .join('\n\n');

return [{ json: { relatorio, edicao, data: agora.toISODate(), ...entrada } }];

// Divide o relatório em mensagens, porque o Telegram aceita até 4.096 caracteres
// e cerca de 100 formatações (negritos e links) em cada uma.
// Cada seção começa em uma mensagem nova, e nada é cortado no meio de um bloco.
const MAX_CARACTERES = 3800;
const MAX_FORMATACOES = 90;
const { relatorio } = $input.first().json;

// O limite conta o texto que aparece na tela, sem as tags e sem o endereço dos links
const tamanho = (texto) => texto.replace(/<[^>]+>/g, '').replace(/&(amp|lt|gt);/g, '&').length;
const formatacoes = (texto) => (texto.match(/<(b|a)[ >]/g) || []).length;
const iniciaSecao = (bloco) => /^(⭐|📌|🔎)/.test(bloco);

const mensagens = [];
let atual = '';
for (const bloco of relatorio.split('\n\n')) {
  const junto = atual ? `${atual}\n\n${bloco}` : bloco;
  const cabe = tamanho(junto) <= MAX_CARACTERES && formatacoes(junto) <= MAX_FORMATACOES;
  if (atual && (iniciaSecao(bloco) || !cabe)) {
    mensagens.push(atual);
    atual = bloco;
  } else {
    atual = junto;
  }
}
if (atual) mensagens.push(atual);

return mensagens.map((mensagem) => ({ json: { mensagem } }));

// Monta uma linha da aba "noticias" para cada inserção enviada no relatório.
// Guarda só título, veículo, data, link, classificação e o resumo da IA.
const { grupos, edicao } = $('Montar relatório').first().json;
const fuso = 'America/Sao_Paulo';
const data_envio = $now.setZone(fuso).toFormat('dd/LL/yyyy HH:mm');

const linhas = grupos.flatMap((g) =>
  g.insercoes.map((i) => ({
    data_envio,
    edicao,
    titulo: i.titulo,
    veiculo: i.veiculo,
    link: i.link,
    data_publicacao: DateTime.fromISO(i.data).setZone(fuso).toFormat('dd/LL/yyyy HH:mm'),
    tom: g.sentimento,
    aderencia: g.aderencia,
    resumo: g.resumo,
  }))
);

return linhas.map((linha) => ({ json: linha }));

// Monta a linha da aba "log", com o resumo desta execução.
// O início da execução é o que a próxima usa para buscar só o que saiu depois.
const { edicao, resumo_triagem, resumo_redacao, resumo_revisao } = $('Montar relatório').first().json;
const coleta = $('Limpeza').first().json.resumo_coleta;
const erros = [...resumo_triagem.erros, ...resumo_redacao.erros, ...resumo_revisao.erros];

return [{ json: {
  inicio_execucao: DateTime.fromISO(coleta.inicio).setZone('America/Sao_Paulo').toISO(),
  edicao,
  coletadas: coleta.coletadas,
  classificadas: resumo_triagem.classificadas,
  relevantes: resumo_redacao.insercoes,
  fatos: resumo_redacao.grupos_relevantes,
  resumos_retirados: resumo_revisao.resumos_retirados,
  erros: erros.join(' | '),
} }];

// Define até onde a busca volta: desde o início da última execução, mais 1 hora de folga.
// Sem histórico, usa 24 horas. O teto de 7 dias é o limite prático do RSS do Google News.
const PADRAO_HORAS = 24;
const FOLGA_HORAS = 1;
const TETO_HORAS = 168;

const inicios = $('Ler log').all()
  .map((item) => DateTime.fromISO(String(item.json.inicio_execucao || '')))
  .filter((data) => data.isValid);

const horas = inicios.length
  ? Math.ceil($now.diff(DateTime.max(...inicios), 'hours').hours) + FOLGA_HORAS
  : PADRAO_HORAS;
const horas_janela = Math.min(horas, TETO_HORAS);

return [{ json: { horas_janela, dias_busca: Math.ceil(horas_janela / 24) } }];
